#include <string>
#include <unordered_set>
#include <cctype>

class Solution {
public:
    int passwordStrength(std::string password) {
        std::unordered_set<char> st(password.begin(), password.end());
        int ans = 0;
        for (char ch : st) {
            if (std::islower(ch)) ans += 1;
            else if (std::isupper(ch)) ans += 2;
            else if (std::isdigit(ch)) ans += 3;
            else if (ch == '!' || ch == '@' || ch == '#' || ch == '$') ans += 5;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int passwordStrength(String password) {
        Set<Character> st = new HashSet<>();
        for (char c : password.toCharArray()) st.add(c);
        int ans = 0;
        for (char ch : st) {
            if (Character.isLowerCase(ch)) ans += 1;
            else if (Character.isUpperCase(ch)) ans += 2;
            else if (Character.isDigit(ch)) ans += 3;
            else if ("!@#$".indexOf(ch) != -1) ans += 5;
        }
        return ans;
    }
}

function passwordStrength(password) {
    const st = new Set(password);
    let ans = 0;
    for (const ch of st) {
        if (ch >= 'a' && ch <= 'z') ans += 1;
        else if (ch >= 'A' && ch <= 'Z') ans += 2;
        else if (ch >= '0' && ch <= '9') ans += 3;
        else if (ch === '!' || ch === '@' || ch === '#' || ch === '$') ans += 5;
    }
    return ans;
}
